/// Call the calendar-event-delete entrypoint on one registered bridge.
uint32_t call_calendar_event_delete(
    JNIEnv *env,
    uint64_t session_handle,
    NativeStringRef id
) {
    jobject bridge = resolve_bridge(env, session_handle);
    if (bridge == nullptr) {
        return HOST_STATUS_NOT_FOUND;
    }

    jstring id_value = java_string_or_null(env, id);

    jint status = env->CallIntMethod(
        bridge,
        eventDelete_method,
        id_value
    );
    if (id_value != nullptr) { env->DeleteLocalRef(id_value); }
    env->DeleteLocalRef(bridge);

    if (env->ExceptionCheck()) {
        env->ExceptionClear();
        return HOST_STATUS_FAILED;
    }

    return static_cast<uint32_t>(status);
}
